#!/usr/bin/env bash
# Prepares the JFR recording fixtures the tests use.
#
# By default this script is fully offline: it copies small checked-in
# recordings into the locations the test suites reference:
#
#   test-fixtures/synthetic.jfr
#       A ~250 KB recording generated by test-fixtures/GenerateRecording.java
#       (single-producer JDK flight recording: hundreds of execution samples with
#       stack traces, allocation samples, GC events). Copied to the
#       test-ap.jfr / test-jfr.jfr slots: the unit tests in this repository
#       only need a real JDK recording with samples, not gigabytes of them.
#
#   jfr-shell-tck/src/main/resources/tck-test.jfr
#       A ~2.3 MB Datadog-profiled recording (used by the TCK). Copied to the
#       test-dd.jfr slot: the jfr-mcp integration tests and the go-parser
#       tests expect a Datadog-flavoured recording.
#
# CI relies on this and downloads nothing. Pass --full to fetch the
# original full-size recordings from Dropbox (test-ap.jfr ~170 MB,
# test-jfr.jfr ~1.7 GB, test-dd.jfr ~2.3 MB — byte-identical to the
# checked-in tck-test.jfr); they are only useful for benchmarks and scale
# experiments. Files are only fetched when missing - delete the small
# copies first if you want the full ones.
set -euo pipefail

HERE=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" >/dev/null 2>&1 && pwd)

FULL=0
for arg in "$@"; do
  case "$arg" in
    --full) FULL=1 ;;
    -h|--help)
      # Print everything up to the first line of code (the comment header).
      sed -n '2,/^set -euo pipefail$/{/^set -euo pipefail$/!p;}' "$0"
      exit 0
      ;;
    *)
      echo "unknown argument: $arg (expected --full or --help)" >&2
      exit 2
      ;;
  esac
done

# Ensure target directories exist
mkdir -p "$HERE/demo/src/test/resources"
mkdir -p "$HERE/parser-core/src/test/resources"

TCK_FIXTURE="$HERE/jfr-shell-tck/src/main/resources/tck-test.jfr"
SYNTHETIC_FIXTURE="$HERE/test-fixtures/synthetic.jfr"

AP_FILE="$HERE/demo/src/test/resources/test-ap.jfr"
JFR_FILE="$HERE/demo/src/test/resources/test-jfr.jfr"
DD_JFR_FILE="$HERE/demo/src/test/resources/test-dd.jfr"

if [ "$FULL" = "1" ]; then
  download() {
    local url="$1" dest="$2"
    # Download to a temp file and move into place only on success, so an
    # interrupted run can never leave a truncated recording that later
    # runs would mistake for a complete one.
    if command -v curl >/dev/null 2>&1; then
      curl -fL "$url" -o "$dest.part" && mv "$dest.part" "$dest"
    elif command -v wget >/dev/null 2>&1; then
      wget -q -O "$dest.part" "$url" && mv "$dest.part" "$dest"
    else
      echo "Neither curl nor wget is available to download $url" >&2
      return 1
    fi
  }

  # Use direct-download links (dl=1) and follow redirects.
  # NOTE: dl=0 serves Dropbox's HTML preview page, not the file.
  AP_URL="https://www.dropbox.com/scl/fi/lp5bj8adi3l7jge9ykayr/test-ap.jfr?rlkey=28wghlmp7ge4bxnan9ccwarby&dl=1"
  JFR_URL="https://www.dropbox.com/scl/fi/5uhp13h9ltj38joyqmwo5/test-jfr.jfr?rlkey=p0wmznxgm7zud6xzaydled69c&dl=1"
  DD_JFR_URL="https://www.dropbox.com/scl/fi/1hqtubs3pawamcydyp2t9/test-dd.jfr?rlkey=ug101qmbjgfd9xa1b2svq0zn8&st=oof9fvmo&dl=1"

  if [ ! -f "$AP_FILE" ]; then
    echo "Downloading test-ap.jfr -> $AP_FILE"
    download "$AP_URL" "$AP_FILE"
  fi

  if [ ! -f "$JFR_FILE" ]; then
    echo "Downloading test-jfr.jfr -> $JFR_FILE"
    download "$JFR_URL" "$JFR_FILE"
  fi

  if [ ! -f "$DD_JFR_FILE" ]; then
    echo "Downloading test-dd.jfr -> $DD_JFR_FILE"
    download "$DD_JFR_URL" "$DD_JFR_FILE"
  fi
else
  if [ ! -f "$SYNTHETIC_FIXTURE" ]; then
    echo "Missing checked-in fixture: $SYNTHETIC_FIXTURE" >&2
    exit 1
  fi
  if [ ! -f "$TCK_FIXTURE" ]; then
    echo "Missing checked-in fixture: $TCK_FIXTURE" >&2
    exit 1
  fi
  # Synthetic fixture for the generic sample-heavy slots; the real
  # Datadog recording for the dd slot. Different content by design — do not
  # collapse to one file.
  for dest in "$AP_FILE" "$JFR_FILE"; do
    if [ ! -f "$dest" ]; then
      echo "Copying synthetic.jfr -> $dest"
      cp -f "$SYNTHETIC_FIXTURE" "$dest"
    fi
  done
  if [ ! -f "$DD_JFR_FILE" ]; then
    echo "Copying tck-test.jfr -> $DD_JFR_FILE"
    cp -f "$TCK_FIXTURE" "$DD_JFR_FILE"
  fi
fi

PARSER_RES_DIR="$HERE/parser-core/src/test/resources"
mkdir -p "$PARSER_RES_DIR"

# Copy into parser test resources to keep parser tests self-contained.
if [ ! -f "$PARSER_RES_DIR/test-ap.jfr" ]; then
  cp -f "$AP_FILE" "$PARSER_RES_DIR/test-ap.jfr"
fi
if [ ! -f "$PARSER_RES_DIR/test-jfr.jfr" ]; then
  cp -f "$JFR_FILE" "$PARSER_RES_DIR/test-jfr.jfr"
fi
if [ ! -f "$PARSER_RES_DIR/test-dd.jfr" ]; then
  cp -f "$DD_JFR_FILE" "$PARSER_RES_DIR/test-dd.jfr"
fi
